<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import client from '@/api/client'
import { teacherApi, type Classroom, type RosterStudent } from '@/api/teacher'
import KnownAssignmentsView from './KnownAssignmentsView.vue'
import LearningAdviceView from './LearningAdviceView.vue'
import TeacherWorkspaceView from './TeacherWorkspaceView.vue'
import TeacherMistakesView from './TeacherMistakesView.vue'
import AssignmentPlansView from './AssignmentPlansView.vue'
import { learningApi } from '@/api/learning'

const route = useRoute()
const section = computed(() => route.path.split('/')[2] || 'workbench')
const titles: Record<string,string> = { workbench:'工作台', assignments:'作业管理', data:'教学数据', bank:'题库与AI' }
const busy=ref(false), error=ref(''), message=ref('')
const papers=ref<any[]>([]), assignments=ref<any[]>([]), classes=ref<Classroom[]>([]), roster=ref<RosterStudent[]>([])
const classId=ref(0), paperId=ref(0), assignmentId=ref(0), current=ref<any>(null), dashboard=ref<any>(null)
const uploadFiles=ref<File[]>([]), rights=ref(false), subject=ref('math'), grade=ref('grade9')
const batchDifficulty=ref(''), selectedIds=ref<number[]>([]), knowledge=ref(''), catalog=ref<any[]>([])
const bank=ref<any[]>([]), selectedAsset=ref(0), manual=ref(false)
const asset=ref({ question_text:'', correct_answer:'', analysis:'', options:'', difficulty:'easy', knowledge_points:'' })
const title=ref(''), date=ref(new Date().toLocaleDateString('sv-SE')), due=ref(''), defaultRule=ref('required')
const rules=ref<Record<string,string>>({}), suggestions=ref<any[]>([]), selectedQuestion=ref<any>(null)
const detail=ref(''), preview=ref(''), previewType=ref(''), transferTarget=ref(0), transferNumber=ref('')
const practiceStudents=ref<number[]>([])
const historyVariants=ref<any[]>([]), historySubmissions=ref<any[]>([])
const calendarOpen=ref(route.query.panel==='calendar')
const assistantOpen=ref(route.query.panel==='assistant')
function practiceForQuestion(q:any){practiceStudents.value=q.answers.filter((a:any)=>a.outcome==='wrong').map((a:any)=>a.student_id);detail.value='';selectedQuestion.value=q;queueMicrotask(()=>{detail.value='practice'})}
const requestKeys=new Map<string,string>()
const catalogVersion=ref('')
const urls:string[]=[]
function key(scope:string){ if(!requestKeys.has(scope))requestKeys.set(scope,crypto.randomUUID());return requestKeys.get(scope)! }
function detailError(e:any){const d=e.response?.data?.detail;return typeof d==='string'?d: d?JSON.stringify(d):e.message||'操作失败'}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e:any){error.value=detailError(e)}finally{busy.value=false}}
async function load(){const [p,a,c]=await Promise.all([client.get('/teacher-v2/papers'),client.get('/teacher-v2/assignments'),teacherApi.classes()]);papers.value=p.data.items;assignments.value=a.data.items;classes.value=c;if(!classId.value&&c.length)classId.value=c[0].id}
async function loadRoster(){roster.value=classId.value?await teacherApi.roster(classId.value):[];rules.value={};suggestions.value=[]}
async function prepareRoster(){await client.post(`/teacher-v2/classes/${classId.value}/prepare-roster`);await loadRoster();message.value='名册实体已就绪，不创建账号、不绑定身份。请重新核对逐人要求。'}
function attrs(){const a:Record<string,any>={subject:subject.value,grade:grade.value};if(batchDifficulty.value)a.difficulty=batchDifficulty.value;if(knowledge.value.trim())a.knowledge_points=knowledge.value.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean);if(catalogVersion.value)a.catalog_version=catalogVersion.value;return a}
function overridePoints(target:any,e:Event){const values=(e.target as HTMLInputElement).value.split(/[,，、\n]/).map(s=>s.trim()).filter(Boolean);if(values.length)target.knowledge_points=values;else delete target.knowledge_points}
async function upload(){if(!rights.value||!uploadFiles.value.length)throw Error('请选择文件并确认使用权');const fd=new FormData();uploadFiles.value.forEach(f=>fd.append('files',f));fd.append('attributes',JSON.stringify(attrs()));fd.append('rights_confirmed','true');const scope='upload:'+uploadFiles.value.map(f=>`${f.name}:${f.size}:${f.lastModified}`).join('|')+JSON.stringify(attrs());const r=await client.post('/teacher-v2/batches',fd,{headers:{'Idempotency-Key':key(scope)}});await load();message.value=`已导入${r.data.papers.length}套原卷，每份文件独立保存。需关联并确认题目，不会伪造OCR结果。`}
async function bulk(){if(!selectedIds.value.length)throw Error('请先勾选套卷');const batchIds=[...new Set(papers.value.filter(p=>selectedIds.value.includes(p.id)).map(p=>p.batch_id))];for(const id of batchIds)await client.put(`/teacher-v2/batches/${id}/attributes`,attrs());await load();current.value=null;message.value='公共属性已更新到所选套卷所在的整个批次；单卷与单题显式覆盖继续优先。'}
async function edit(p:any){current.value=JSON.parse(JSON.stringify(p));selectedAsset.value=0;bank.value=[]}
async function save(){const p=current.value;const r=await client.put(`/teacher-v2/papers/${p.id}`,{expected_revision:p.revision,title:p.title,attributes:p.attributes,questions:p.questions.map((q:any)=>({asset_id:q.asset_id,number:String(q.number),max_score:Number(q.max_score),overrides:q.overrides||{}}))});await load();current.value=r.data;message.value='草稿已保存。已发布的原卷、答案和每人要求不受影响。'}
async function confirm(){await save();const r=await client.post(`/teacher-v2/papers/${current.value.id}/confirm`);current.value=r.data;await load();message.value='整套题干、答案、解析与来源已确认，可用于发布。'}
async function searchBank(){if(!classId.value)throw Error('先选择有任教学科权限的班级');const r=await client.get('/assignment-plans/question-bank/search',{params:{class_id:classId.value,subject:subject.value,grade:grade.value}});bank.value=r.data.data.items;message.value=bank.value.length?'请选择审核题目':'没有匹配的已审核题目，可补充有权使用的题干、答案与解析。'}
function attach(){if(!selectedAsset.value||!current.value)return;const qs=current.value.questions;if(qs.some((q:any)=>q.asset_id===selectedAsset.value))throw Error('该题已在本套卷');let number=qs.length+1;while(qs.some((q:any)=>q.number===String(number)))number++;qs.push({asset_id:selectedAsset.value,number:String(number),max_score:10,overrides:{}})}
async function createAsset(attachCurrent=true){let options=null;if(asset.value.options.trim())options=JSON.parse(asset.value.options);const r=await client.post('/teacher-v2/assets',{subject:subject.value,grade:grade.value,question_text:asset.value.question_text,options,correct_answer:asset.value.correct_answer,analysis:asset.value.analysis,difficulty:asset.value.difficulty,knowledge_points:asset.value.knowledge_points.split(/[,，、\n]/).map(s=>s.trim()).filter(Boolean),confirmed:true});selectedAsset.value=r.data.asset_id;if(attachCurrent)attach();manual.value=false;message.value=attachCurrent?'教师补充题目已关联到当前草稿，请保存整套后确认。':`已保存教师确认题目 #${r.data.asset_id}，未添加到任何原卷或发布作业。`}
async function lookup(){const r=await client.get('/teacher-v2/catalog',{params:{subject:subject.value,query:knowledge.value}});catalog.value=r.data.items;message.value=r.data.notice}
function chooseKnowledge(c:any){knowledge.value=c.name;catalogVersion.value=c.version;if(manual.value)asset.value.knowledge_points=c.name}
async function source(p:any){const r=await client.get(`/teacher-v2/papers/${p.id}/source`,{responseType:'blob'});preview.value=URL.createObjectURL(r.data);urls.push(preview.value);previewType.value=p.format}
async function assignmentSource(){const r=await client.get(`/teacher-v2/assignments/${assignmentId.value}/source`,{params:{student_id:0},responseType:'blob'});preview.value=URL.createObjectURL(r.data);urls.push(preview.value);previewType.value=activeAssignment.value.source_format}
async function prepareTemplate(){await client.post(`/teacher-v2/assignments/${assignmentId.value}/prepare-template`);detail.value='known';message.value='已从同一原卷准备本地草稿模板（或复用已有模板），请逐页标定、确认空白参考后激活；未通过匹配的仍拒判。'}
async function transfer(mode:string){const target=papers.value.find(p=>p.id===transferTarget.value);if(!target)throw Error('请选择目标套卷');await client.post(`/teacher-v2/papers/${current.value.id}/transfer`,{target_paper_id:target.id,number:transferNumber.value,mode,expected_source_revision:current.value.revision,expected_target_revision:target.revision});const id=current.value.id;await load();await edit(papers.value.find(p=>p.id===id));message.value='已更新草稿；两套已发布历史不变。'}
async function suggest(){if(!paperId.value||!classId.value)throw Error('先选择套卷和班级');suggestions.value=(await client.get(`/teacher-v2/papers/${paperId.value}/suggest-requirements`,{params:{class_id:classId.value}})).data.requirements;message.value=suggestions.value.length?'建议已生成，尚未应用；核对依据后点击采用。':'可信证据不足，保留教师默认策略；没有自动改变要求。'}
function applySuggestions(){for(const s of suggestions.value)rules.value[`${s.student_id}:${s.number}`]=s.requirement;message.value='建议已填入待发布草稿，仍可修改；发布确认前不生效。'}
const selectedPaper=computed(()=>papers.value.find(p=>p.id===paperId.value))
async function publish(){if(!selectedPaper.value||!classId.value||!title.value.trim())throw Error('请选择确认套卷、班级并填写标题');const requirements=[];for(const r of roster.value){if(!r.student_id)continue;for(const q of selectedPaper.value.questions){const value=rules.value[`${r.student_id}:${q.number}`];if(value)requirements.push({student_id:r.student_id,number:q.number,requirement:value,reason:'教师核对后按人按题覆盖'})}}const body={expected_revision:selectedPaper.value.revision,class_id:classId.value,title:title.value,assignment_date:date.value,due_at:due.value||null,confirmed:true,default_requirement:defaultRule.value,requirements};const r=await client.post(`/teacher-v2/papers/${paperId.value}/publish`,{...body,request_key:key('publish:'+paperId.value+JSON.stringify(body))});await load();assignmentId.value=r.data.assignment_id;await showDashboard();message.value='已按单一原卷发布全班，每人必做选做及答案均已冻结。'}
async function showDashboard(){if(!assignmentId.value)return;dashboard.value=null;selectedQuestion.value=null;detail.value='';historyVariants.value=[];historySubmissions.value=[];dashboard.value=(await client.get(`/teacher-v2/assignments/${assignmentId.value}/dashboard`)).data;if(dashboard.value.mode!=='uniform_mixed'){const [v,s]=await Promise.all([learningApi.variants(assignmentId.value),teacherApi.submissions(assignmentId.value)]);historyVariants.value=v.variants;historySubmissions.value=s}}
function rate(v:number|null){return v===null||v===undefined?'—（无可信样本）':(v*100).toFixed(1)+'%'}
const activeAssignment=computed(()=>assignments.value.find(a=>a.id===assignmentId.value))
function showDetail(kind:string){detail.value=detail.value===kind?'':kind}
async function studentResult(s:any){if(!s.task_id)return;const r=await teacherApi.studentEntityResult(assignmentId.value,s.student_id);selectedQuestion.value={result:r}}
watch(classId,()=>void run(loadRoster))
watch(section,()=>{error.value='';message.value='';detail.value=''})
onMounted(()=>run(async()=>{await load();await loadRoster()}))
onBeforeUnmount(()=>urls.forEach(u=>URL.revokeObjectURL(u)))
</script>

<template>
 <section class="v2">
  <header><div><h1>{{ titles[section] }}</h1><p>同一套原卷，全班统一题号，教师确认每人必做与选做。</p></div><button :disabled="busy" @click="run(load)">刷新</button></header>
  <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="message" role="status" class="message">{{ message }}</p>
  <div v-if="section==='workbench'" class="card"><h2>最近作业与待处理</h2><p v-if="!assignments.length">还没有可访问作业，先建班录入名册，再导入套卷。</p><article v-for="a in assignments.slice(0,8)" :key="a.id" class="row"><div><b>{{ a.title }}</b><p>{{ a.assignment_date }} · {{ a.mode==='uniform_mixed'?'单套混合卷':'历史作业（原模式保留）' }}</p></div><button @click="run(async()=>{assignmentId=a.id;await showDashboard()})">查看作业与待处理</button></article><router-link to="/teacher/classes">管理班级学生</router-link> · <router-link to="/teacher/bank">导入与准备套卷</router-link> · <router-link to="/teacher/assignments">发布作业</router-link></div>

  <template v-if="section==='bank'">
   <div class="card"><h2>批量导入原卷</h2><p>每个文件一套卷。支持PDF、DOCX、PNG、JPG；保存原文件，不声称已自动OCR或解析Word题目。</p>
    <label>学科<select v-model="subject"><option value="math">数学</option><option value="physics">物理</option><option value="chemistry">化学</option></select></label>
    <label>年级<select v-model="grade"><option value="grade7">七年级</option><option value="grade8">八年级</option><option value="grade9">九年级</option></select></label>
    <label>批次难度默认<select v-model="batchDifficulty"><option value="">继承题目原属性</option><option value="easy">基础</option><option value="medium">中等</option><option value="hard">挑战</option></select></label>
    <label>知识点<input v-model="knowledge" placeholder="可空；多个用逗号分隔" /></label><button :disabled="busy" @click="run(lookup)">查询已采教材目录</button>
    <details v-if="catalog.length"><summary>人教2024九年级目录（部分册次仍缺失）</summary><button v-for="c in catalog" :key="c.id" :title="c.path.join(' / ')" @click="chooseKnowledge(c)">{{ c.name }}</button></details>
    <input type="file" multiple accept=".pdf,.docx,.png,.jpg,.jpeg" aria-label="选择原卷文件" @change="uploadFiles=Array.from(($event.target as HTMLInputElement).files||[])" />
    <label><input type="checkbox" v-model="rights" />我有权在本班使用这些原卷</label><button :disabled="busy||!rights||!uploadFiles.length" @click="run(upload)">导入为独立套卷</button>
   </div>
   <details class="card"><summary>教师自建审核题目（仅入题库，不绑定原卷）</summary><p>学科年级沿用上方选择。教师明确核对来源、题干、答案与解析；不调用AI，不伪称源于导入文件。</p><label>题库题干<textarea v-model="asset.question_text" /></label><label>题库选项JSON<textarea v-model="asset.options" placeholder='{"A":"10","B":"11","C":"12","D":"13"}' /></label><label>题库标准答案<input v-model="asset.correct_answer" /></label><label>题库解析<textarea v-model="asset.analysis" /></label><label>题库知识点<input v-model="asset.knowledge_points" /></label><label>题库难度<select v-model="asset.difficulty"><option value="easy">基础</option><option value="medium">中等</option><option value="hard">挑战</option></select></label><button :disabled="busy" @click="run(()=>createAsset(false))">确认有权使用及答案正确，保存到题库</button></details>
   <div class="card"><h2>套卷库</h2><button :disabled="busy||!selectedIds.length" @click="run(bulk)">把上方公共属性应用到勾选卷的整批次</button><p>会影响同一批次的其他套卷；单卷/单题覆盖优先，已发布快照不变。</p>
    <table><thead><tr><th>选择</th><th>套卷 / 原文件</th><th>题数 / 知识点</th><th>答案与异常</th><th>操作</th></tr></thead><tbody><tr v-for="p in papers" :key="p.id"><td><input type="checkbox" v-model="selectedIds" :value="p.id" /></td><td>{{ p.title }}<small>{{ p.source_name }} · {{ p.format }} · v{{ p.revision }}</small></td><td>{{ p.question_count }}题<small>{{ [...new Set(p.resolved_questions.flatMap((q:any)=>q.attributes.knowledge_points))].join('、')||'待关联' }}</small></td><td>{{ p.status==='CONFIRMED'?'整套已确认':'待确认' }}<small>{{ p.exceptions.join('；') }}</small></td><td><button @click="run(()=>edit(p))">展开调整</button><button @click="run(()=>source(p))">预览原卷</button></td></tr></tbody></table>
   </div>
   <div v-if="current" class="card"><h2>编辑套卷 #{{ current.id }}</h2><label>标题<input v-model="current.title" /></label><label>单卷难度<select v-model="current.attributes.difficulty"><option :value="undefined">继承批次/题目</option><option value="easy">基础</option><option value="medium">中等</option><option value="hard">挑战</option></select></label>
    <label>单卷知识点覆盖（空则继承）<input :value="current.attributes.knowledge_points?.join('、')" @input="overridePoints(current.attributes,$event)" /></label><label>单卷知识点版本<input v-model="current.attributes.catalog_version" placeholder="继承批次版本" /></label><label>单卷题型<input v-model="current.attributes.question_type" placeholder="未填写继承原题" /></label>
    <p>题目须与原卷逐题对应，题号不可被系统擅自重排。题干、答案、解析来源须明确。</p>
    <label>班级（题库权限）<select v-model="classId"><option v-for="c in classes" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><button :disabled="busy" @click="run(searchBank)">选用已审核题目</button><button @click="manual=!manual">补充题干与标准答案</button>
    <div v-if="bank.length"><select v-model="selectedAsset" aria-label="选择审核题目"><option :value="0">请选择</option><option v-for="q in bank" :key="q.id" :value="q.id">{{ q.id }} · {{ q.question_text.slice(0,80) }}</option></select><button @click="run(async()=>attach())">关联到本卷</button></div>
    <div v-if="manual" class="inset"><h3>教师补充并确认一题</h3><label>题干<textarea v-model="asset.question_text" /></label><label>选项JSON（非选择题可空）<textarea v-model="asset.options" placeholder='{"A":"1","B":"2","C":"3","D":"4"}' /></label><label>标准答案<input v-model="asset.correct_answer" /></label><label>解析<textarea v-model="asset.analysis" /></label><label>知识点<input v-model="asset.knowledge_points" /></label><label>原题难度<select v-model="asset.difficulty"><option value="easy">基础</option><option value="medium">中等</option><option value="hard">挑战</option></select></label><button :disabled="busy" @click="run(createAsset)">确认有权使用且答案正确，添加本题</button></div>
    <article v-for="(q,i) in current.questions" :key="q.asset_id" class="inset"><label>原题号<input v-model="q.number" /></label><label>分值<input v-model.number="q.max_score" type="number" min="1" /></label><label>单题难度覆盖<select v-model="q.overrides.difficulty"><option :value="undefined">继承单卷/批次/题目</option><option value="easy">基础</option><option value="medium">中等</option><option value="hard">挑战</option></select></label><label>单题知识点覆盖<input :value="q.overrides.knowledge_points?.join('、')" @input="overridePoints(q.overrides,$event)" placeholder="空则继承上层" /></label><label>单题知识点版本<input v-model="q.overrides.catalog_version" /></label><label>单题题型<input v-model="q.overrides.question_type" /></label><p>{{ current.resolved_questions.find((r:any)=>r.asset_id===q.asset_id)?.question_text || '新关联题目，保存后展开审核' }}</p><details><summary>题干、答案、解析与继承来源</summary><pre>{{ current.resolved_questions.find((r:any)=>r.asset_id===q.asset_id) }}</pre></details><button @click="current.questions.splice(i,1)">从草稿移除</button><button v-if="i>0" @click="current.questions.splice(i-1,0,current.questions.splice(i,1)[0])">上移</button></article>
    <label>移/复制题号<input v-model="transferNumber" /></label><label>目标套卷<select v-model="transferTarget"><option :value="0">请选择</option><option v-for="p in papers.filter(p=>p.id!==current.id)" :key="p.id" :value="p.id">{{ p.title }}</option></select></label><button :disabled="busy" @click="run(()=>transfer('copy'))">复制已保存题目</button><button :disabled="busy" @click="run(()=>transfer('move'))">移动已保存题目</button>
    <p>{{ current.exceptions.join('；') }}</p><button :disabled="busy" @click="run(save)">保存草稿</button><button :disabled="busy||!current.questions.length" @click="run(confirm)">整套核对无误并确认</button>
   </div>
   <div class="card"><h2>题目检索与和AI说想法</h2><p>付费模型额度为0，采用本地检索与教师审核。套卷统一发布在作业管理完成，不提供重复的旧三层卷创建向导。</p><button @click="assistantOpen=!assistantOpen">{{ assistantOpen?'收起题库助手':'打开题库助手' }}</button><AssignmentPlansView v-if="assistantOpen" /></div>
  </template>

  <div v-if="section==='assignments'" class="card"><h2>统一原卷发布</h2><label>套卷<select v-model="paperId" aria-label="发布套卷"><option :value="0">选择已确认套卷</option><option v-for="p in papers.filter(p=>p.status==='CONFIRMED')" :key="p.id" :value="p.id">{{ p.title }}（{{ p.question_count }}题）</option></select></label><label>班级<select v-model="classId"><option v-for="c in classes" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>标题<input v-model="title" /></label><label>教学日期<input v-model="date" type="date" /></label><label>截止<input v-model="due" type="datetime-local" /></label>
   <p v-if="roster.some(r=>!r.student_id)" class="error">部分名册尚无学生实体，不能以空ID填写每人要求。<button :disabled="busy" @click="run(prepareRoster)">准备名册实体（不创建登录账号，仅班级负责人）</button></p><p v-if="!roster.length">本班暂无学生，请先录入名册。</p>
   <label>全班默认<select v-model="defaultRule"><option value="required">全部必做（证据不足默认）</option><option value="optional">全部选做（教师明确覆盖）</option></select></label><button :disabled="busy||!paperId" @click="run(suggest)">读取可信学情建议（不自动应用）</button><button v-if="suggestions.length" @click="applySuggestions">审阅后采用建议到草稿</button><pre v-if="suggestions.length">{{ suggestions }}</pre>
   <div v-if="selectedPaper&&roster.length&&roster.every(r=>r.student_id)" class="scroll"><table><thead><tr><th>学生</th><th v-for="q in selectedPaper.questions" :key="q.number">第{{ q.number }}题</th></tr></thead><tbody><tr v-for="r in roster" :key="r.id"><td>{{ r.student_name }} {{ r.bound?'':'（未绑定）' }}</td><td v-for="q in selectedPaper.questions" :key="q.number"><select v-model="rules[`${r.student_id}:${q.number}`]" :aria-label="r.student_name+'第'+q.number+'题要求'"><option :value="undefined">全班默认</option><option value="required">必做</option><option value="optional">选做</option></select></td></tr></tbody></table></div><p>难度不决定必做/选做；发布后题干、答案、知识点版本、按人要求不可原地更改。提交仍为1～9张一次一份任务。</p><button :disabled="busy||!paperId||!title.trim()||!roster.length||roster.some(r=>!r.student_id)" @click="run(publish)">确认原卷及每人要求并发布</button>
  </div>

  <div v-if="section==='data'||section==='assignments'" class="card"><h2>单次作业</h2><select v-model="assignmentId" aria-label="选择作业看板"><option :value="0">选择作业</option><option v-for="a in assignments" :key="a.id" :value="a.id">{{ a.title }} · {{ a.assignment_date }}</option></select><button :disabled="busy||!assignmentId" @click="run(showDashboard)">查看作业看板</button></div>
  <div v-if="section==='data'" class="card"><button @click="calendarOpen=!calendarOpen">{{ calendarOpen?'收起班级日历':'查看班级日历与历史成绩' }}</button><TeacherWorkspaceView v-if="calendarOpen" initial-tab="daily" /></div>
  <div v-if="dashboard" class="card"><h2>{{ dashboard.title }} · 作业看板</h2><p>{{ dashboard.notice }}</p>
   <template v-if="dashboard.mode==='uniform_mixed'"><div class="counts"><span v-for="(label,k) in {expected:'应交',submitted:'实交',unsubmitted:'未交',overdue:'逾期',graded:'已批改',waiting_review:'待核对',processing:'处理中',exceptions:'异常'}" :key="k">{{ label }}<b>{{ dashboard.counts[k] }}</b></span></div>
    <button :disabled="busy" @click="run(prepareTemplate)">用同一原卷准备校对模板</button>
    <h3>逐题统计 · 点击下钻</h3><table><thead><tr><th>原题号</th><th>有效学生</th><th>错误 / 部分正确</th><th>错误率</th><th>操作</th></tr></thead><tbody><tr v-for="q in dashboard.questions" :key="q.snapshot_question_id"><td>第{{ q.number }}题</td><td>{{ q.valid_count }}</td><td>{{ q.wrong_count }} / {{ q.partial_count }}</td><td>{{ rate(q.wrong_rate) }}</td><td><button @click="selectedQuestion=q">查看题目与原卷证据</button><button @click="practiceForQuestion(q)">据可信学情建专项草稿</button></td></tr></tbody></table>
    <h3>知识点错误率</h3><table><thead><tr><th>知识点</th><th>可信作答次数 / 人数</th><th>错误率</th></tr></thead><tbody><tr v-for="k in dashboard.knowledge_points" :key="k.id"><td>{{ k.id }}</td><td>{{ k.valid_count }} / {{ k.student_ids.length }}</td><td>{{ rate(k.wrong_rate) }}</td></tr></tbody></table>
    <h3>全班学生 · 不同必做范围不排名</h3><table><thead><tr><th>学生</th><th>状态</th><th>必做完成</th><th>选做参与</th><th>追溯</th></tr></thead><tbody><tr v-for="s in dashboard.students" :key="s.student_id"><td>{{ s.name }}</td><td>{{ s.status }} {{ s.overdue?'逾期':'' }}</td><td>{{ s.required_done }}/{{ s.required_count }} · {{ rate(s.required_completion) }}</td><td>{{ s.optional_done }}/{{ s.optional_count }}</td><td><button v-if="s.task_id" @click="run(()=>studentResult(s))">查看原提交结果</button></td></tr></tbody></table>
    <h3>局部异常处理</h3><p>先沿用安全恢复，不能确定仍拒判；没有人工核对不纳入可信分母。</p><p v-for="e in dashboard.exceptions" :key="e.task_id">{{ e.task_id }} · {{ e.status }} <button @click="showDetail('known')">进入本作业模板/括号核对</button></p><button @click="showDetail('known')">原卷模板与括号校对</button><button @click="showDetail('practice')">专项训练与结果回流</button><button @click="run(assignmentSource)">查看同一原卷</button>
   </template>
   <template v-else><p>历史作业只读，沿用原统计合同，不补造个人要求，不重复创建或改写三版本。</p><h3>原版本题面、答案与解析</h3><article v-for="v in historyVariants" :key="v.id"><h4>{{ v.level_label }} · 原版本{{ v.version }}</h4><ol><li v-for="(q,i) in v.questions" :key="q.id||i"><p>{{ q.question_text }}</p><p>答案：{{ q.correct_answer || '未登记' }} · 解析：{{ q.analysis || '未登记' }}</p></li></ol></article><p v-if="!historyVariants.length">此历史作业没有登记版本题面。</p><h3>已有学生提交与成绩</h3><p v-for="s in historySubmissions" :key="s.student_entity_id||s.student_id">{{ s.student_name }} · {{ s.task_status||'未提交' }} · {{ s.total_score??'无有效成绩' }} <button v-if="s.task_id" @click="run(()=>studentResult({...s,student_id:s.student_entity_id||s.student_id}))">查看原提交结果</button></p><details><summary>历史统计数据与来源</summary><pre>{{ dashboard.legacy_dashboard }}</pre></details></template>
   <button @click="showDetail('corrections')">本作业错题与订正审核</button>
   <details v-if="selectedQuestion" open><summary>题目 / 结果追溯</summary><pre>{{ selectedQuestion }}</pre></details>
   <KnownAssignmentsView v-if="detail==='known'" :key="assignmentId" :initial-class-id="activeAssignment?.class_id" :initial-assignment-id="assignmentId" />
   <LearningAdviceView v-if="detail==='practice'" :key="assignmentId" :initial-class-id="activeAssignment?.class_id" :initial-subject="activeAssignment?.subject" :initial-student-ids="practiceStudents" />
   <TeacherMistakesView v-if="detail==='corrections'" :key="assignmentId" :initial-class-id="activeAssignment?.class_id" :initial-assignment-id="assignmentId" />
  </div>
  <div v-if="preview" class="card"><button @click="preview=''">关闭原卷预览</button><img v-if="['png','jpg','jpeg'].includes(previewType)" :src="preview" alt="已保存原卷" /><iframe v-else-if="previewType==='pdf'" :src="preview" title="已保存原卷PDF" /><a v-else :href="preview" download="原卷.docx">下载原始Word核对（未伪造Office预览）</a></div>
 </section>
</template>
<style scoped>
.v2{padding:24px;max-width:1300px;margin:auto;color:#17223b}header,.row{display:flex;justify-content:space-between;align-items:center;gap:16px}.card{background:white;border:1px solid #dce3ef;border-radius:12px;padding:22px;margin:18px 0}.inset{background:#f7f9fd;border-left:3px solid #aec4f5;padding:14px;margin:12px 0}h1{font-size:26px}h2{font-size:20px}p,small{color:#53627a}small{display:block;margin-top:6px}label{display:inline-block;margin:8px;vertical-align:top}input,select,textarea,button{padding:9px;border:1px solid #bdcbe0;border-radius:6px;max-width:100%;font:inherit}label>input:not([type=checkbox]),label>select,label>textarea{display:block;margin-top:5px}textarea{min-width:230px;min-height:70px}button{background:#edf3ff;color:#1d4ed8;margin:5px;cursor:pointer}button:disabled{opacity:.5;cursor:default}table{width:100%;border-collapse:collapse;text-align:left}th,td{border-bottom:1px solid #e4eaf4;padding:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.error{background:#fff0f0;color:#a31818;padding:14px}.message{background:#eef7ff;padding:14px}.counts{display:flex;flex-wrap:wrap;gap:14px}.counts span{padding:14px;min-width:85px;background:#f2f6fc}.counts b{display:block;font-size:25px}img{max-width:100%;max-height:700px}iframe{display:block;width:100%;height:700px;border:0}.scroll{overflow:auto}a{color:#2154c4}
</style>
